import { describe, expect, it } from 'vitest';
import { LOCALES } from './config';
import altFormSpecies from './alt-form-species.json';

/**
 * The form marker's contract.
 *
 * The marker is the one grapheme on a tile that says which form you are looking
 * at — `A` for Alolan, `ア` in Japanese, `阿` in Chinese. It is generated by
 * `npm run i18n:names`, and the rules it has to satisfy are not obvious, so
 * they are asserted rather than trusted.
 *
 * The rule that matters most is the third one. A marker is a *claim* that this
 * form differs from its siblings, so two siblings sharing a marker is worse
 * than neither having one: it looks like information and isn't. Several
 * plausible ways of generating markers fail exactly here, which is why the
 * generator does not use them —
 *
 *  - the first grapheme of the form *label* works in languages that lead with
 *    the distinguishing word (`Alolan Form`, `アローラのすがた`) and collapses in
 *    those that lead with a shared one: French `Forme d'Alola` and
 *    `Forme de Galar` both give `F`;
 *  - the first grapheme of the *sweet item* separates Alcremie's six in English,
 *    Japanese, Korean, Chinese and French, and gives six identical letters in
 *    German (`Zucker-…`), Spanish (`Confite…`) and Italian (`Bonbon…`).
 *
 * So the generator takes the marker from the region's own name, adds the sweet
 * item only in the languages where it discriminates, and marks nothing else.
 */

const ALT_FORM_SPECIES = altFormSpecies as Record<string, number>;

interface Catalog {
  species: string[];
  forms: Record<string, string>;
  formMark: Record<string, string>;
}

// Eager glob rather than fs: this file is typechecked under the `src` project,
// which has no Node types, and the sibling names.test.ts loads them the same way.
const FILES = import.meta.glob<Catalog>('./names/*.json', { import: 'default', eager: true });
const catalogs = new Map<string, Catalog>(
  LOCALES.map((l) => [l, FILES[`./names/${l}.json`]]),
);

/** The app's alt forms, grouped by the species they belong to. */
const bySpecies = new Map<number, string[]>();
for (const [appId, speciesId] of Object.entries(ALT_FORM_SPECIES)) {
  if (!bySpecies.has(speciesId)) bySpecies.set(speciesId, []);
  bySpecies.get(speciesId)!.push(appId);
}

const graphemes = (s: string) => [
  ...new Intl.Segmenter(undefined, { granularity: 'grapheme' }).segment(s.normalize('NFC')),
];

describe('form marker', () => {
  it.each(LOCALES)('%s marks every regional form', (locale) => {
    const { formMark } = catalogs.get(locale)!;
    // 57 of the app's 64 alt forms are regional. Every one gets a marker in
    // every language, because a region is a bare noun everywhere.
    const marked = Object.keys(formMark).length;
    expect(marked).toBeGreaterThanOrEqual(57);
  });

  it.each(LOCALES)('%s uses exactly one grapheme per marker', (locale) => {
    const { formMark } = catalogs.get(locale)!;
    const tooLong = Object.entries(formMark).filter(([, m]) => graphemes(m).length !== 1);
    // Two graphemes would not fit the space the tile reserves, and a marker
    // split mid-syllable — which `[0]` on a Korean string produces — would be
    // an unreadable fragment rather than an abbreviation.
    expect(tooLong).toEqual([]);
  });

  /**
   * Tauros is the one species whose forms a region marker cannot separate: all
   * three Paldean breeds are Paldean, so all three are correctly `P`.
   *
   * The breed — Combat, Blaze, Aqua — is what distinguishes them, and it is not
   * available to abbreviate. `pokemon_form_names` gives the same "Paldean Form"
   * for all three in every language but English, and Scarlet/Violet's own text
   * mentions the breeds only inside Pokédex prose ("This kind of Tauros, known
   * as the Combat Breed, is distinguished by…"), never as a standalone label.
   *
   * They are still told apart on the tile, by the thing that actually differs:
   * their types. Combat is Fighting, Blaze is Fighting/Fire, Aqua is
   * Fighting/Water, and the type badges sit directly under the name.
   *
   * Listed explicitly so this stays a decision. Any *other* collision is a bug.
   */
  const SHARED_MARKER_OK = new Set([128]);

  it.each(LOCALES)('%s never gives two forms of one species the same marker', (locale) => {
    const { formMark } = catalogs.get(locale)!;
    const clashes: string[] = [];
    for (const [speciesId, appIds] of bySpecies) {
      if (SHARED_MARKER_OK.has(speciesId)) continue;
      const marks = appIds.map((id) => formMark[id]).filter(Boolean);
      const dupes = marks.filter((m, i) => marks.indexOf(m) !== i);
      if (dupes.length) clashes.push(`species ${speciesId}: ${marks.join(' ')}`);
    }
    expect(clashes).toEqual([]);
  });
});
